// Only third-party initdb runs outside the coverage worker. Use the same installed engine and,
// for the cold-start smoke, the exact shim source generated by the covered parent process.
import { writeFile } from 'node:fs/promises';
import { PGlite } from '@electric-sql/pglite';

const [mode, input] = process.argv.slice(2);
let proof;
if (mode === 'catalog') {
  const engine = new PGlite();
  try {
    await engine.waitReady;
    const catalog = Buffer.from(await (await engine.dumpDataDir('none')).arrayBuffer());
    await writeFile(input, catalog, { flag: 'wx' });
    proof = { mode, bytes: catalog.byteLength };
  } finally {
    await engine.close();
  }
  proof.closed = engine.closed;
} else if (mode === 'cold') {
  const { source, queries } = JSON.parse(input);
  if (typeof source !== 'string' || !Array.isArray(queries) || queries.length !== 3) {
    throw new Error('Invalid cold-start fixture input');
  }
  const engines = [];
  const constructorArgumentCounts = [];
  const importer = async (specifier) => {
    if (specifier !== '@electric-sql/pglite') throw new Error('Unexpected database fixture import');
    return { PGlite: class extends PGlite {
      constructor(...args) {
        super(...args);
        engines.push(this);
        constructorArgumentCounts.push(args.length);
      }
    } };
  };
  try {
    const module = { exports: {} };
    new Function('module', 'exports', 'console', '__nbaiImport', source.replace(/\bimport\(PGLITE_URL\)/, '__nbaiImport(PGLITE_URL)'))(
      module, module.exports, console, importer,
    );
    const pool = new module.exports.Pool();
    const results = [];
    for (const query of queries) results.push(await pool.query(query.text, query.values));
    proof = { mode, results, engineCount: engines.length, constructorArgumentCounts };
  } finally {
    await Promise.all(engines.map((engine) => engine.close()));
  }
  proof.closed = engines.length > 0 && engines.every((engine) => engine.closed);
} else {
  throw new Error('Unknown database fixture mode');
}
process.stdout.write(JSON.stringify(proof));
